"""Real native SHA with controlled async validator rejection, not corrupt geometry."""
import subprocess,json,re,sys,hashlib
from pathlib import Path
out=Path(sys.argv[1]).resolve();session=sys.argv[2];out.mkdir(parents=True,exist_ok=True);rows=[];downloads=out/'discarded-downloads';downloads.mkdir(exist_ok=True);assert not list(downloads.iterdir())
def call(*a,stdin=None):return subprocess.run(['agent-browser','--session',session,*a],input=stdin,capture_output=True,text=True,check=True,timeout=70).stdout
def ref(label):
 call('wait','--fn','Array.from(document.querySelectorAll("button")).some(e=>e.textContent==='+json.dumps(label)+')')
 s=call('snapshot','-i');m=re.search('button "'+re.escape(label)+'" \[ref=(e\d+)\]',s);assert m,label;return '@'+m[1]
def click(label):call('click',ref(label))
def ready(diagnostic=False):call('wait','--fn',"Array.from(document.querySelectorAll('summary')).some(e=>e.textContent.includes("+json.dumps('UV quality: integrity' if diagnostic else 'UV quality: integrity PASS')+"))")
def frames():call('eval',"(async()=>{await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));return 'two native frames';})()")
def hook():call('eval','--stdin',stdin=(Path(__file__).parent/'export-validation-browser-harness.js').read_text())
def hold(label):ready(label=='Export diagnostic tooth cut');call('eval','window.__exportIntentTest.arm()');click(label);call('wait','--fn','window.__exportIntentTest.pending()')
def release(fail):call('eval','window.__exportIntentTest.release('+str(fail).lower()+')');frames()
def fill(n):call('fill','[aria-label="Ball radius (mm)"]',str(n));click('Apply part edit')
call('--download-path',str(downloads),'open','http://127.0.0.1:4179/viewer.html?editor=elements');call('upload','input[type=file]',str(out/'base.elements.json'));ready();hook()
hold('Export selected GLB + source JSON');release(True);assert 'Controlled export-validator' in call('get','text','[role=status]');rows.append('Current export failure remains visible')
