hold('Export project GLB + source JSON');fill(2.5);release(True);assert 'Controlled export-validator'not in call('get','text','[role=status]');rows.append('Old whole-export error discarded after Apply')
hold('Export selected GLB + source JSON');click('Undo');release(True);assert 'Controlled export-validator'not in call('get','text','[role=status]');rows.append('Old selected-export error discarded after Undo')
hold('Export selected GLB + source JSON');call('upload','input[type=file]',str(out/'base.elements.json'));ready();release(True);assert 'Controlled export-validator'not in call('get','text','[role=status]');rows.append('Old selected-export error discarded after new source import')
hold('Export selected GLB + source JSON');fill(2.4);release(False);assert '0 bytes last GLB' in call('get','text','[role=status]');rows.append('Superseded successful selected export emits no artifact')
call('screenshot',str(out/'element.png'));call('eval','window.__exportIntentTest.restore()');call('open','http://127.0.0.1:4179/viewer.html?editor=workspace');call('upload','[aria-label="Load workspace JSON"]',str(out/'base.workspace.json'));call('wait','--fn',"document.querySelector('[aria-label=\"Workspace asset\"] option[value=bearing]')!==null");call('select','[aria-label="Workspace asset"]','bearing');click('ball_0000');ready();hook()
hold('Export workspace GLB + JSON');release(True);assert 'Controlled export-validator' in call('get','text','[role=alert]');rows.append('Current workspace export failure remains visible')
hold('Export workspace GLB + JSON');fill(2.3);release(True);assert 'Controlled export-validator'not in call('get','text','[role=alert]');rows.append('Old workspace export error discarded after child Apply')
hold('Export workspace GLB + JSON');fill(2.2);release(False);assert not call('get','text','[role=alert]').strip();rows.append('Superseded workspace success discarded without stale error')
hold('Export selected GLB + source JSON');call('select','[aria-label="Workspace asset"]','animal');ready();release(False);assert not list(downloads.iterdir());rows.append('Unmounted child export emits no files after active-asset switch');call('screenshot',str(out/'workspace.png'));call('eval','window.__exportIntentTest.restore()');call('open','http://127.0.0.1:4179/viewer.html?editor=elements');call('wait','--fn',"document.querySelector('h1')?.textContent==='Element editor'");s=call('snapshot','-i');m=re.search('combobox "Domain Pack"[^\n]*?ref=(e\d+)',s);assert m;call('select','@'+m[1],'mechanical.spur-gear.visual');call('fill','form input','spur_gear');click('Select');call('select','[aria-label="Connected feature ID"]','tooth_0000');ready(True);hook()
hold('Export diagnostic tooth cut');release(True);assert 'Controlled export-validator' in call('get','text','[role=status]');rows.append('Current diagnostic tooth export failure remains visible')
hold('Export diagnostic tooth cut');call('fill','[aria-label="Part roughness"]','0.44');click('Apply part edit');release(True);assert 'Controlled export-validator'not in call('get','text','[role=status]');rows.append('Old diagnostic tooth export error discarded after PBR Apply')
hold('Export diagnostic tooth cut');call('fill','[aria-label="Part roughness"]','0.48');click('Apply part edit');release(False);assert not list(downloads.iterdir());rows.append('Superseded diagnostic tooth success emits no files');assert 'integrity FAIL' in call('get','text','[aria-label="UV quality"]');ready(True);call('eval','window.__exportIntentTest.arm()');click('Export selected GLB + source JSON');call('wait','--fn','window.__exportIntentTest.pending()');release(False);assert 'UV integrity failed' in call('get','text','[role=status]');assert not list(downloads.iterdir());rows.append('Ordinary gear export keeps existing UV failure blocked; diagnostic is not approval');call('eval','window.__exportIntentTest.restore()');report={'pass':True,'cases':rows,'method':'native controls/actual export and native SHA bytes; only validator completion/fault timing controlled; no React state or geometry corruption','notRun':['parent Workspace unmount completion'],'discardedDownloadFiles':len(list(downloads.iterdir())),'sourceHashes':{p:hashlib.sha256(Path(p).read_bytes()).hexdigest()for p in ['src/ElementEditor.tsx','src/WorkspaceEditor.tsx','scripts/export-validation-browser-harness.js']}};(out/'browser-evidence.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report));call('close')
